    static long[][] dp;
    static long[][][] memo;

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        n = Integer.parseInt(br.readLine());
        s = br.readLine();
        m = s.length();
        if (m > n) {
            System.out.println(0);
            return;
        }
        fail = new int[m + 1][2];
        buildFailure();
        dp = new long[n + 1][m + 1];
        for (int i = 0; i <= n; i++) {
            Arrays.fill(dp[i], -1);
        }
        long total = 0;
        for (int start = 0; start < 2; start++) {
            int nextState = nextState(0, start);
            if (nextState < m) {
                total += solve(n - 1, nextState);
            }
        }
        System.out.println(total);
    }

    static void buildFailure() {
        for (int state = 0; state <= m; state++) {
            for (int c = 0; c < 2; c++) {
                if (state < m && (s.charAt(state) - '0') == c) {
                    fail[state][c] = state + 1;
                } else if (state == 0) {
                    fail[state][c] = 0;
                } else {
                    fail[state][c] = fail[fail[state - 1][c]][c];
                }
            }
        }
    }

    static int nextState(int state, int c) {
        return fail[state][c];
    }

    static long solve(int pos, int state) {
        if (state == m) {
            return 1L << (n - pos);
        }
        if (pos == 0) {
            return 0;
        }
        if (dp[pos][state] != -1) {
            return dp[pos][state];
        }
        long res = 0;
        for (int c = 0; c < 2; c++) {
            int nextState = nextState(state, c);
            res += solve(pos - 1, nextState);
        }
        return dp[pos][state] = res;
    }
}
