        for (int i = 0; i <= m; i++) {
            for (int c = 0; c < 2; c++) {
                if (i < m && (s.charAt(i) - '0') == c) {
                    fail[i][c] = i + 1;
                } else if (i == 0) {
                    fail[i][c] = 0;
                } else {
                    fail[i][c] = fail[fail[i][c]][c];
                }
            }
        }
        dp = new long[n + 1][m + 1];
        for (int i = 0; i <= n; i++) {
            Arrays.fill(dp[i], -1);
        }
        memo = new long[n + 1][m + 1][2];
        for (int i = 0; i <= n; i++) {
            for (int j = 0; j <= m; j++) {
                Arrays.fill(memo[i][j], -1);
            }
        }
        long total = 1L << n;
        long bad = 0;
        for (int start = 0; start < m; start++) {
            for (int first = 0; first < 2; first++) {
                if (s.charAt(start) - '0' != first) continue;
                int nextState = start + 1;
                if (nextState == m) continue;
                bad += solve(n - 1, nextState, first);
            }
        }
        System.out.println(total - bad);
    }

    static long solve(int pos, int state, int first) {
        if (pos == 0) {
            return 1;
        }
        if (memo[pos][state][first] != -1) {
            return memo[pos][state][first];
        }
        long res = 0;
        for (int c = 0; c < 2; c++) {
            int nextState = fail[state][c];
            if (nextState == m) continue;
            res += solve(pos - 1, nextState, first);
        }
        return memo[pos][state][first] = res;
    }
}
