import java.io.*;
import java.util.*;

public class Main {
    static int n;
    static String s;
    static int m;
    static int[] fail;
    static long[][] dp;
    static long[][] memo;

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        n = Integer.parseInt(br.readLine());
        s = br.readLine();
        m = s.length();
        fail = new int[m + 1];
        computeFail();
        dp = new long[n + 1][m + 1];
        for (int i = 0; i <= n; i++) Arrays.fill(dp[i], -1);
        memo = new long[n + 1][m + 1];
        for (int i = 0; i <= n; i++) Arrays.fill(memo[i], -1);
        long total = (1L << n);
        long bad = countBad();
        System.out.println(total - bad);
    }

    static void computeFail() {
        fail[0] = -1;
        for (int i = 1; i <= m; i++) {
            int j = fail[i - 1];
            while (j >= 0 && s.charAt(j) != s.charAt(i - 1)) j = fail[j];
            fail[i] = j + 1;
        }
    }

    static int nextState(int state, char c) {
        while (state >= 0 && (state == m || s.charAt(state) != c)) state = fail[state];
        return state + 1;
    }

    static long countBad() {
        return solve(0, 0);
    }

    static long solve(int pos, int state) {
        if (state == m) return 0;
        if (pos == n) return 1;
        if (memo[pos][state] != -1) return memo[pos][state];
        long res = 0;
        res += solve(pos + 1, nextState(state, '0'));
        res += solve(pos + 1, nextState(state, '1'));
        return memo[pos][state] = res;
    }
}
