        while (state > 0 && s.charAt(state) != c) {
            state = fail[state - 1];
        }
        if (s.charAt(state) == c) {
            state++;
        }
        return state;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        n = Integer.parseInt(br.readLine());
        s = br.readLine();
        m = s.length();

        computeFail();

        // dp[pos][state][started]
        long[][][] dp = new long[n + 1][m + 1][2];
        dp[0][0][0] = 1;

        for (int pos = 0; pos < n; pos++) {
            for (int state = 0; state <= m; state++) {
                for (int started = 0; started < 2; started++) {
                    if (dp[pos][state][started] == 0) continue;
                    for (char c : new char[]{'0', '1'}) {
                        int ns = nextState(state, c);
                        int nstarted = started;
                        if (ns == m) {
                            nstarted = 1;
                        }
                        if (nstarted == 1) {
                            // Once started, we don't care about the state anymore
                            dp[pos + 1][0][1] += dp[pos][state][started];
                        } else {
                            dp[pos + 1][ns][nstarted] += dp[pos][state][started];
                        }
                    }
                }
            }
        }

        long ans = 0;
        for (int state = 0; state <= m; state++) {
            ans += dp[n][state][1];
        }
        System.out.println(ans);
    }
}
